B.a8P=s([B.avX,B.ava],t.L)
B.awm=new A.cF("children","Children",B.a8P)
B.a1T=s(["M\xe3 ho\xe1 \u0111\u01b0\u1eddng truy\u1ec1n b\u1eb1ng HTTPS / TLS.","M\u1eadt kh\u1ea9u b\u0103m b\u1eb1ng bcrypt; m\xe3 \u0111\u0103ng nh\u1eadp (token) c\xf3 th\u1eddi h\u1ea1n ng\u1eafn v\xe0 \u0111\u01b0\u1ee3c l\u01b0u trong kho b\u1ea3o m\u1eadt c\u1ee7a h\u1ec7 \u0111i\u1ec1u h\xe0nh.","M\xe3 l\xe0m m\u1edbi \u0111\u01b0\u1ee3c thay m\u1edbi sau m\u1ed7i l\u1ea7n d\xf9ng; n\u1ebfu m\u1ed9t m\xe3 c\u0169 b\u1ecb d\xf9ng l\u1ea1i, m\u1ecdi phi\xean li\xean quan b\u1ecb hu\u1ef7 ngay \u0111\u1ec3 ch\u1ed1ng \u0111\xe1nh c\u1eafp phi\xean.","C\u01a1 s\u1edf d\u1eef li\u1ec7u v\xe0 b\u1ed9 nh\u1edb \u0111\u1ec7m ch\u1ec9 truy c\u1eadp \u0111\u01b0\u1ee3c t\u1eeb m\xe1y ch\u1ee7 \u1ee9ng d\u1ee5ng; quy\u1ec1n qu\u1ea3n tr\u1ecb gi\u1edbi h\u1ea1n \u1edf ng\u01b0\u1eddi th\u1eadt s\u1ef1 c\u1ea7n.","Gi\u1edbi h\u1ea1n t\u1ea7n su\u1ea5t \u0111\u0103ng nh\u1eadp v\xe0 g\u1eedi tin nh\u1eafn \u0111\u1ec3 ch\u1ed1ng d\xf2 m\u1eadt kh\u1ea9u v\xe0 th\u01b0 r\xe1c."],t.s)
