B.awq=new A.cF("breach","Khi x\u1ea3y ra s\u1ef1 c\u1ed1 d\u1eef li\u1ec7u",B.a3j)
B.avq=new A.c4("M\xe1y ch\u1ee7 Pandlish ho\u1eb7c c\xe1c nh\xe0 cung c\u1ea5p n\xeau tr\xean c\xf3 th\u1ec3 \u0111\u1eb7t ngo\xe0i Vi\u1ec7t Nam. Khi chuy\u1ec3n d\u1eef li\u1ec7u c\xe1 nh\xe2n ra n\u01b0\u1edbc ngo\xe0i, ch\xfang m\xecnh l\u1eadp h\u1ed3 s\u01a1 \u0111\xe1nh gi\xe1 t\xe1c \u0111\u1ed9ng chuy\u1ec3n d\u1eef li\u1ec7u theo Lu\u1eadt 91/2025/QH15 v\xe0 g\u1eedi c\u01a1 quan chuy\xean tr\xe1ch khi ph\xe1p lu\u1eadt y\xeau c\u1ea7u. V\u1edbi d\u1eef li\u1ec7u c\u1ee7a ng\u01b0\u1eddi d\xf9ng t\u1ea1i EU / V\u01b0\u01a1ng qu\u1ed1c Anh, ch\xfang m\xecnh \xe1p d\u1ee5ng bi\u1ec7n ph\xe1p b\u1ea3o v\u1ec7 ph\xf9 h\u1ee3p nh\u01b0 \u0110i\u1ec1u kho\u1ea3n h\u1ee3p \u0111\u1ed3ng m\u1eabu (SCC) c\u1ee7a \u1ee6y ban ch\xe2u \xc2u.")
