B.avP=new A.c4("Khi b\u1ea1n g\u1eedi tin nh\u1eafn qua trang Li\xean h\u1ec7, ch\xfang m\xecnh l\u01b0u: ch\u1ee7 \u0111\u1ec1, n\u1ed9i dung, t\xean v\xe0 email (n\u1ebfu b\u1ea1n cung c\u1ea5p), ng\xf4n ng\u1eef, n\u1ec1n t\u1ea3ng (web / iOS / Android), th\u1eddi \u0111i\u1ec3m g\u1eedi v\xe0 \u2014 n\u1ebfu b\u1ea1n \u0111ang \u0111\u0103ng nh\u1eadp \u2014 li\xean k\u1ebft t\u1edbi t\xe0i kho\u1ea3n. Ch\xfang m\xecnh kh\xf4ng l\u01b0u \u0111\u1ecba ch\u1ec9 IP c\xf9ng tin nh\u1eafn.")
B.avT=new A.c4("B\u1ea1n c\u1ea7n \u0111\xe1nh d\u1ea5u \u0111\u1ed3ng \xfd tr\u01b0\u1edbc khi g\u1eedi. Tin nh\u1eafn ch\u1ec9 d\xf9ng \u0111\u1ec3 tr\u1ea3 l\u1eddi, h\u1ed7 tr\u1ee3 b\u1ea1n v\xe0 c\u1ea3i thi\u1ec7n Pandlish, v\xe0 \u0111\u01b0\u1ee3c t\u1ef1 \u0111\u1ed9ng xo\xe1 sau 12 th\xe1ng.")
B.a1J=s([B.avP,B.avT],t.L)
B.awt=new A.cF("feedback","Tin nh\u1eafn li\xean h\u1ec7 v\xe0 g\xf3p \xfd",B.a1J)
B.a1v=s(["We do not sell, rent, trade or otherwise deal in personal data in any form \u2014 trading personal data is prohibited under Law 91/2025/QH15.","Pandlish contains no advertising SDKs, ad networks, analytics or third-party tracking tools.",'As defined by the CCPA / CPRA, we do not "sell" or "share" personal information for cross-context behavioural advertising, including that of people under 16.',"We do not use your data for solely automated decisions with legal or similarly significant effects on you."],t.s)
